import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

ln_cpp_decl = r"""
#include <torch/extension.h>
#include <vector>
torch::Tensor layernorm_forward(torch::Tensor x,
                                c10::optional<torch::Tensor> weight,
                                c10::optional<torch::Tensor> bias,
                                std::vector<int64_t> normalized_shape,
                                double eps);
"""

ln_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

namespace {

constexpr int kThreads = 512;

// One CTA per normalization row. Row statistics (mean / rstd) are computed
// with fp64 accumulators (inputs may be ~1e3 with ~1e-1 variance, where a
// fp32 sum-of-squares would catastrophically cancel). The normalize pass is
// pure fp32 using an exact two-term mean subtraction: (x - mhi) - mlo.
__global__ void layernorm_rows_kernel(
    const float* __restrict__ Xp,
    const float* __restrict__ Wp,
    const float* __restrict__ Bp,
    float* __restrict__ Yp,
    int64_t row_len,
    float eps)
{
  using namespace cute;

  const int64_t row  = blockIdx.x;
  const float*  xrow = Xp + row * row_len;
  float*        yrow = Yp + row * row_len;

  const bool    vec  = ((row_len & 3) == 0);
  const int64_t nvec = vec ? (row_len >> 2) : 0;

  // CuTe global tensors, float4-vectorized body
  Tensor gX = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(xrow)), make_shape(nvec));
  Tensor gY = make_tensor(make_gmem_ptr(reinterpret_cast<float4*>(yrow)),       make_shape(nvec));
  Tensor gW = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(Wp)),   make_shape(nvec));
  Tensor gB = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(Bp)),   make_shape(nvec));

  // CuTe global tensors, scalar tail / fallback
  Tensor gXs = make_tensor(make_gmem_ptr(xrow), make_shape(row_len));
  Tensor gYs = make_tensor(make_gmem_ptr(yrow), make_shape(row_len));
  Tensor gWs = make_tensor(make_gmem_ptr(Wp),   make_shape(row_len));
  Tensor gBs = make_tensor(make_gmem_ptr(Bp),   make_shape(row_len));

  const int tid = threadIdx.x;

  // ---------------- Pass 1: statistics ----------------
  double s0 = 0.0, s1 = 0.0, q0 = 0.0, q1 = 0.0;

  if (vec) {
    int64_t i = tid;
    for (; i + 3 * kThreads < nvec; i += 4 * kThreads) {
      float4 a = gX(i);
      float4 b = gX(i + kThreads);
      float4 c = gX(i + 2 * kThreads);
      float4 d = gX(i + 3 * kThreads);

      s0 += (double)a.x + (double)a.y + (double)a.z + (double)a.w;
      s1 += (double)b.x + (double)b.y + (double)b.z + (double)b.w;
      s0 += (double)c.x + (double)c.y + (double)c.z + (double)c.w;
      s1 += (double)d.x + (double)d.y + (double)d.z + (double)d.w;

      q0 += (double)a.x * a.x + (double)a.y * a.y + (double)a.z * a.z + (double)a.w * a.w;
      q1 += (double)b.x * b.x + (double)b.y * b.y + (double)b.z * b.z + (double)b.w * b.w;
      q0 += (double)c.x * c.x + (double)c.y * c.y + (double)c.z * c.z + (double)c.w * c.w;
      q1 += (double)d.x * d.x + (double)d.y * d.y + (double)d.z * d.z + (double)d.w * d.w;
    }
    for (; i < nvec; i += kThreads) {
      float4 v = gX(i);
      s0 += (double)v.x + (double)v.y + (double)v.z + (double)v.w;
      q0 += (double)v.x * v.x + (double)v.y * v.y + (double)v.z * v.z + (double)v.w * v.w;
    }
  }
  for (int64_t j = (nvec << 2) + tid; j < row_len; j += kThreads) {
    double v = (double)gXs(j);
    s0 += v;
    q0 += v * v;
  }

  // Block reduction of (sum, sumsq)
  __shared__ double sh_sum[kThreads / 32];
  __shared__ double sh_sqs[kThreads / 32];
  __shared__ double sh_mean, sh_rstd;

  double sum = s0 + s1;
  double sqs = q0 + q1;

  #pragma unroll
  for (int off = 16; off > 0; off >>= 1) {
    sum += __shfl_down_sync(0xffffffffu, sum, off);
    sqs += __shfl_down_sync(0xffffffffu, sqs, off);
  }

  const int lane = tid & 31;
  const int wid  = tid >> 5;
  if (lane == 0) {
    sh_sum[wid] = sum;
    sh_sqs[wid] = sqs;
  }
  __syncthreads();

  if (wid == 0) {
    constexpr int NW = kThreads / 32;
    sum = (lane < NW) ? sh_sum[lane] : 0.0;
    sqs = (lane < NW) ? sh_sqs[lane] : 0.0;
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
      sum += __shfl_down_sync(0xffffffffu, sum, off);
      sqs += __shfl_down_sync(0xffffffffu, sqs, off);
    }
    if (lane == 0) {
      double inv_n = 1.0 / (double)row_len;
      double mean  = sum * inv_n;
      double var   = sqs * inv_n - mean * mean;
      var = var > 0.0 ? var : 0.0;
      sh_mean = mean;
      sh_rstd = rsqrt(var + (double)eps);
    }
  }
  __syncthreads();

  const double mean = sh_mean;
  const double rstd = sh_rstd;
  // Split mean so the subtraction stays exact in fp32
  const float mhi = (float)mean;
  const float mlo = (float)(mean - (double)mhi);
  const float rf  = (float)rstd;

  auto norm = [&](float v) -> float { return ((v - mhi) - mlo) * rf; };

  // ---------------- Pass 2: normalize + affine ----------------
  if (vec) {
    int64_t i = tid;
    // Use two float4 batches per iteration to reduce register pressure and
    // allow better SM occupancy while retaining vectorized memory access.
    for (; i + kThreads < nvec; i += 2 * kThreads) {
      float4 a = gX(i);
      float4 b = gX(i + kThreads);
      float4 wa = make_float4(1.f, 1.f, 1.f, 1.f);
      float4 wb = wa;
      float4 ba = make_float4(0.f, 0.f, 0.f, 0.f);
      float4 bb = ba;
      if (Wp != nullptr) {
        wa = gW(i);
        wb = gW(i + kThreads);
      }
      if (Bp != nullptr) {
        ba = gB(i);
        bb = gB(i + kThreads);
      }
      float4 oa, ob;
      oa.x = fmaf(norm(a.x), wa.x, ba.x);
      oa.y = fmaf(norm(a.y), wa.y, ba.y);
      oa.z = fmaf(norm(a.z), wa.z, ba.z);
      oa.w = fmaf(norm(a.w), wa.w, ba.w);
      ob.x = fmaf(norm(b.x), wb.x, bb.x);
      ob.y = fmaf(norm(b.y), wb.y, bb.y);
      ob.z = fmaf(norm(b.z), wb.z, bb.z);
      ob.w = fmaf(norm(b.w), wb.w, bb.w);
      gY(i) = oa;
      gY(i + kThreads) = ob;
    }
    for (; i < nvec; i += kThreads) {
      float4 v = gX(i);
      float4 w = make_float4(1.f, 1.f, 1.f, 1.f);
      float4 b = make_float4(0.f, 0.f, 0.f, 0.f);
      if (Wp != nullptr) w = gW(i);
      if (Bp != nullptr) b = gB(i);
      float4 o;
      o.x = fmaf(norm(v.x), w.x, b.x);
      o.y = fmaf(norm(v.y), w.y, b.y);
      o.z = fmaf(norm(v.z), w.z, b.z);
      o.w = fmaf(norm(v.w), w.w, b.w);
      gY(i) = o;
    }
  }
  for (int64_t j = (nvec << 2) + tid; j < row_len; j += kThreads) {
    float v = gXs(j);
    float w = (Wp != nullptr) ? (float)gWs(j) : 1.f;
    float b = (Bp != nullptr) ? (float)gBs(j) : 0.f;
    gYs(j) = fmaf(norm(v), w, b);
  }
}

} // namespace

torch::Tensor layernorm_forward(torch::Tensor x,
                                c10::optional<torch::Tensor> weight,
                                c10::optional<torch::Tensor> bias,
                                std::vector<int64_t> normalized_shape,
                                double eps)
{
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(!normalized_shape.empty(), "normalized_shape must be non-empty");

  int64_t row_len = 1;
  for (auto d : normalized_shape) {
    TORCH_CHECK(d > 0, "normalized_shape dims must be positive");
    row_len *= d;
  }

  const int64_t nd = x.dim();
  const int64_t nnd = (int64_t)normalized_shape.size();
  TORCH_CHECK(nd >= nnd, "x must have at least normalized_shape dims");
  for (int64_t k = 0; k < nnd; ++k) {
    TORCH_CHECK(x.size(nd - nnd + k) == normalized_shape[k],
                "x trailing dims must match normalized_shape");
  }

